    /// Given x ≥ 1, return the smallest s ≥ 1 such that 5*s ≥ x.
    /// Equivalently s = ceil(x/5).  We prove:
    ///   s ≥ 1,
    ///   5*s ≥ x,
    ///   5*(s - 1) < x.
    pub fn min_steps(x: i8) -> i8 {
        // precondition: the caller must give x ≥ 1
        requires(x >= 1);
        // postcondition: we get the minimal s ≥ 1 with 5*s ≥ x
        ensures(|s: i8| s >= 1 && 5*s >= x && 5*(s - 1) < x);

        // split off quotient and remainder; on positives i8 div/mod behave as in ℤ
        let base: i8 = x / 5;
        let rem: i8  = x % 5;
        // standard fact about modulo
        assert(0 <= rem && rem < 5);

        // if there's any remainder we must bump the quotient by 1
        let s: i8 = if rem == 0 { base } else { base + 1 };
        // s must be at least 1 when x ≥ 1
        assert(s >= 1);

        // now prove the two inequalities in the postcondition
        if rem == 0 {
            // exact division case: 5*s = x
            assert(5*s == x);
            // hence 5*(s-1) = x - 5 < x
            assert(5*(s - 1) == x - 5);
            assert(x - 5 < x);
        } else {
            // non‐exact case: s = base+1
            // 5*s - x = (5*(base+1)) - (5*base + rem) = 5 - rem > 0
            assert(5*s - x == 5 - rem);
            assert(5 - rem > 0);
            // so 5*s ≥ x
            assert(5*s >= x);

            // and (s-1) = base, so 5*(s-1) = 5*base < x because rem>0
            assert(5*(s - 1) == 5*base);
            assert(5*base < x);
        }

        s
    }

